// Open issues of the workspace that carry a profile, optionally only those
// assigned to one agent.
func (q *Queries) ListOpenIssuesWithModelProfile(ctx context.Context, arg ListOpenIssuesWithModelProfileParams) ([]ListOpenIssuesWithModelProfileRow, error) {
	rows, err := q.db.Query(ctx, listOpenIssuesWithModelProfile, arg.WorkspaceID, arg.AgentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListOpenIssuesWithModelProfileRow{}
	for rows.Next() {
		var i ListOpenIssuesWithModelProfileRow
		if err := rows.Scan(
			&i.ID,
			&i.Number,
			&i.Title,
			&i.Status,
			&i.AssigneeType,
			&i.AssigneeID,
			&i.ModelProfileID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockModelProfilesInWorkspace = `-- name: LockModelProfilesInWorkspace :many
SELECT id, when_exhausted_profile_id FROM model_profile
WHERE workspace_id = $1
ORDER BY id
FOR UPDATE
`

type LockModelProfilesInWorkspaceRow struct {
	ID                     pgtype.UUID `json:"id"`
	WhenExhaustedProfileID pgtype.UUID `json:"when_exhausted_profile_id"`
}

// Serializes profile writes of one workspace so the cycle check of
// when_exhausted_profile_id sees a stable graph.
func (q *Queries) LockModelProfilesInWorkspace(ctx context.Context, workspaceID pgtype.UUID) ([]LockModelProfilesInWorkspaceRow, error) {
	rows, err := q.db.Query(ctx, lockModelProfilesInWorkspace, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LockModelProfilesInWorkspaceRow{}
	for rows.Next() {
		var i LockModelProfilesInWorkspaceRow
		if err := rows.Scan(&i.ID, &i.WhenExhaustedProfileID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reassignRuntimeModelReferences = `-- name: ReassignRuntimeModelReferences :exec
WITH moved_profile_rows AS (
 UPDATE model_profile_option SET runtime_id = $1 WHERE model_profile_option.runtime_id = $2
), moved_agent_rows AS (
 UPDATE agent_model_option SET runtime_id = $1 WHERE agent_model_option.runtime_id = $2
)
UPDATE runtime_unavailable SET runtime_id = $1 WHERE runtime_unavailable.runtime_id = $2
`

type ReassignRuntimeModelReferencesParams struct {
	NewRuntimeID pgtype.UUID `json:"new_runtime_id"`
	OldRuntimeID pgtype.UUID `json:"old_runtime_id"`
}

// A legacy runtime merged into its successor: model rows and unavailability
// follow the runtime instead of disappearing with it.
func (q *Queries) ReassignRuntimeModelReferences(ctx context.Context, arg ReassignRuntimeModelReferencesParams) error {
	_, err := q.db.Exec(ctx, reassignRuntimeModelReferences, arg.NewRuntimeID, arg.OldRuntimeID)
	return err
}

